from pathlib import Path
import pandas as pd,json,re
O=Path(__file__).resolve().parent
lit=pd.read_csv(O/'jebo_literature_matrix.csv').fillna('')
items=[
('LEE2024','Published 14 pages; inspected FIU version 31 pages including cover','Economic change → conflicting payment prediction → experiment → context-specific result → related literature','0 / 8 in inspected author version','Conceptual motivation; separate related-literature and mechanism sections','Hypothetical WTP explicit; remittance interpretation is contextual','Main heterogeneity tables; no giant specification gallery','About 2 author-manuscript pages'),
('PL2025','Published article number; full-text length unavailable; SSRN version lists29pages','Publisher/author abstract: tax policy → randomized temporal representation → intended allocations → follow-up','Unavailable / unavailable','Not verifiable from accessed abstract','Intended use distinguished from later self-reported use','Not observable','Not observable'),
('FR2025','Published PDF 12pages','Importance of expectations → wording problem → randomized two dimensions → findings','Not fully enumerated / not fully enumerated','Background and related literature, no structural estimation advertised','Subjective responses are the outcome; wording is the treatment','Separate section on practical response behavior','Not fully inspected'),
('PE2024','Published39pages; inspected2021IDBversion43pages','Savings problem → why reminders work → factorial interventions → results','3 / 10 in inspected WP main body','Mechanism-motivated treatment design','Real savings elicited in surveys; not all administrative transactions','Heterogeneity in main, attrition/framing checks appendix','About1WPpage'),
('FO2025','Article number; full-text length unavailable','Abstract: fiscal uncertainty → information intervention → household expectations','Unavailable / unavailable','Theory accompanies experiment per publisher description','Consumption intentions must not be called transactions','Not observable','Not observable'),
('RE2024','Published17pages; inspected2023authorversion60pages incl appendix','Institutional change → crowd-out benchmark → administrative design → distribution','5 / 4 in inspected author main body','Explicit conceptual model and prediction table','Administrative savings; hypothetical issue not applicable','Selected checks in main; extended tests appendix','About2authorpages, section titled Discussion'),
('LS2024','Published9pages','Consumption puzzle → belief model → implications','Unavailable / unavailable','Theory is the contribution','Not an empirical validation example','Not observable','Not observable'),
('RC2024','Article number; full-text length unavailable','Abstract: measurement problem → experimental tasks → validation comparison','Unavailable / unavailable','Not verified','Incentivized allocation tasks; validity explicitly examined','Not observable','Not observable'),
('LB2024','Article number; repository PDF blocked','Abstract: consumer valuation → randomized opacity/feedback → demand','Unavailable / unavailable','Mechanism-targeting design per abstract','Incentivized valuations, unlike present survey','Not observable','Not observable'),
('DI2024','Published11pages','Abstract: disposition puzzle → competing framing → trading records','Unavailable / unavailable','Behavioral framework','Observed trading; no hypothetical endpoint','Not observable','Not observable'),
('OV2024','Published44pages','Abstract: overconfidence/trading → model → investor measures','Unavailable / unavailable','Theory plus observational evidence','Observed trading plus measured literacy','Not observable','Not observable'),
('CA2023','Published15pages','Abstract: denomination policy → transaction model → diary evidence','Unavailable / unavailable','Explicit cash-transaction model','Diary/model outcome','Not observable','Not observable'),
('JT2026','Published article number; final layout unavailable','Survey association → framed experiment → follow-up mechanism evidence','Unavailable / unavailable','Competing budget/salience interpretations','Triangulation across stated and experimental choices','Final placement not observable','Not observable')]
lines=['# JEBO outlet benchmark','', 'Twelve 2023–2025 JEBO articles, selected for substantive proximity rather than representativeness. This is a bounded editorial benchmark, not an estimate of acceptance standards. Metadata are verified; three accessible author/institution full manuscripts and one published PDF opening were inspected. Remaining entries use primary publisher/author abstracts. Unobserved layout fields are explicitly unavailable. Working-version counts are never presented as final published counts.','']
out=[]
for k,length,intro,counts,theory,hyp,rob,con in items:
 r=lit[lit.id==k].iloc[0]
 cache=O/'research_cache'/(k+'_metadata.json');a='not available in machine-readable record'
 if cache.exists():
  ab=re.sub('<[^>]+>',' ',json.loads(cache.read_text(encoding='utf8')).get('abstract','')).strip()
  if ab:a=f'{len(ab.split())} words (Crossref abstract; not layout-adjusted)'
 z=dict(id=k,title=r.title,doi=r.doi,pages_scope=length,abstract_length=a,intro=intro,figures_tables=counts,theory=theory,hypothetical=hyp,main_robustness=rob,conclusion=con,access_scope=r.source_scope)
 out.append(z)
 lines += [f'## {r.authors} ({r.year}) — {r.title}',f'\nSource: {r.url}. Access: {r.source_scope}.',f'\nLength: {length}. Abstract: {a}. Main figures/tables: {counts}.',f'\nOpening: {intro}. Theory: {theory}.',f'\nOutcome discipline: {hyp}. Robustness: {rob}. Conclusion: {con}.','']
pd.DataFrame(out).to_csv(O/'jebo_outlet_benchmark.csv',index=False)
lines += ['## Architecture chosen','', 'Retain nine short substantive sections, an economic-question opening, an approximately1,500–2,000-word introduction, three main figures and three tables. Lead with cells and within-Cash slopes; make cross-form uncertainty visible in the abstract and inference section. Put model-history and broad robustness in the supplement. A conceptual prediction table is sufficient because no structural parameters are identified. A conditional-response accounting result belongs beside distribution plots, not in a mechanism section.','', 'The visible journal examples support question-led behavioral exposition and explicit measurement boundaries. They do not demonstrate that weak adjusted interaction evidence is enough for publication. This paper therefore emphasizes a bounded distributional extension rather than a discovered law. Published-page ranges span9–44 pages; typography and appendices vary too much to infer a useful universal word target. No fabricated median abstract/table count is reported.']
(O/'JEBO_OUTLET_BENCHMARK.md').write_text(('\n'.join(lines)+'\n').replace('Twelve 2023–2025','Thirteen 2023–2026'),encoding='utf8')
c=pd.read_csv(O/'extensive_intensive_cells.csv');cash=c[c.form=='cash']
rows=[]
for r in cash.itertuples():rows.append(dict(study='This study: adult Cash',design='randomized nominal amount',amount=str(r.amount)+' RMB',p_any=r.p_any,midpoint=r.midpoint,top75=r.top75,conditional_midpoint=r.conditional_midpoint,size_pattern='stable coded positive frequency; falling conditional mean',source='extensive_intensive_cells.csv',comparability='six direct bins; essentially-none coded zero; no common horizon'))
for k,pat,comp in [('N12','Positive response frequency increases; conditional response share declines','Filter-first; horizon and negative responses differ; qualitative comparison from institutional WP'),('N25','Small positive extensive movement; conditional decline dominates','Income-relative sizes; different accounts and elicitation; nearest precedent'),('FHN2021','Lower realized/inferred MPC for larger prizes','Administrative lottery evidence; consumption measurement and horizon differ'),('BA2023','Lower estimated MPC at larger programme payments','Regional quasi-experiment, payment restrictions and pandemic context differ'),('JS2026','Reported MPC declines with larger shocks over explicit years','Multiple within-person amounts;2024WP numbers differ from2026published abstract'),('N13','Size pattern differs between affluent and liquidity-poor groups','Income-relative survey gains; no uniform negative slope')]:
 r=lit[lit.id==k].iloc[0];rows.append(dict(study=r.authors+' ('+str(r.year)+')',design=r.population_design_behavior,amount=r.size_variation,p_any='',midpoint='',top75='',conditional_midpoint='',size_pattern=pat,source=r.url,comparability=comp))
pd.DataFrame(rows).to_csv(O/'mpc_size_literature_benchmark.csv',index=False)
s=['# Size benchmark: qualitative comparison, not meta-analysis','', '| Adult Cash amount | Positive category (%) | Midpoint (%) | >75% (%) | Conditional midpoint (%) |','|---|---:|---:|---:|---:|']
for r in cash.itertuples():s.append(f'| {r.amount:,} | {100*r.p_any:.2f} | {100*r.midpoint:.2f} | {100*r.top75:.2f} | {100*r.conditional_midpoint:.2f} |')
s += ['', 'The Cash extensive margin is descriptively stable, whereas conditional means fall. Fuster et al. provide a different extensive pattern, but this is not a clean contradiction: their filter, horizon and permitted responses differ. The closest German factorial predecessor shows broadly similar margin accounting, so the decomposition is explanatory rather than a new discovery. Realized lottery and Korean programme results support size dependence under different identification and measurement conditions. Recent Italian survey evidence makes horizon and household resources central.','', 'Our restricted-use scenarios add a specific institutional dimension; merely combining form and size is not new. Neither a cross-country mechanism test nor a quantitative parameter comparison is warranted. Sources, designs and boundaries are in mpc_size_literature_benchmark.csv. No numerical cross-study test, exchange-rate conversion or new survey contrast is performed.']
(O/'MPC_SIZE_LITERATURE_BENCHMARK.md').write_text('\n'.join(s)+'\n',encoding='utf8')
